using Microsoft.EntityFrameworkCore;using AuthService.Entities;namespace AuthService.Data;public class AuthDbContext(DbContextOptions<AuthDbContext>o):DbContext(o){public DbSet<User>Users=>Set<User>();protected override void OnModelCreating(ModelBuilder m){var e=m.Entity<User>();e.ToTable("users");e.HasKey(x=>x.UserId);e.Property(x=>x.UserId).HasColumnName("user_id").HasDefaultValueSql("gen_random_uuid()");e.Property(x=>x.Username).HasColumnName("username");e.HasIndex(x=>x.Username).IsUnique();e.Property(x=>x.PasswordHash).HasColumnName("password_hash");e.Property(x=>x.Role).HasColumnName("role");e.Property(x=>x.IsActive).HasColumnName("is_active");e.Property(x=>x.CreatedAt).HasColumnName("created_at");}}